n=17
center=n//2
out=[]
for r in range(n):
    row=[0]*n
    if r<=center:
        left,right=center-r,center+r
        row[left]=row[right]=2
        for c in range(left+1,right):
            if (c-r)%4==2:
                row[c]=1
    else:
        for c in range(n):
            if (c-r)%4==2:
                row[c]=1
    out.append(row)
print(out)

